use std::collections::HashMap;

impl LitKind { # [doc = " Converts literal token into a semantic literal."] pub fn from_token_lit (lit : token :: Lit) -> Result < LitKind , LitError > { let token :: Lit { kind , symbol , suffix } = lit ; if let Some (suffix) = suffix && ! kind . may_have_suffix () { return Err (LitError :: InvalidSuffix (suffix)) ; } Ok (match kind { token :: Bool => { assert ! (symbol . is_bool_lit ()) ; LitKind :: Bool (symbol == kw :: True) } token :: Byte => { return unescape_byte (symbol . as_str ()) . map (LitKind :: Byte) . map_err (| _ | panic ! ("failed to unescape byte literal")) ; } token :: Char => { return unescape_char (symbol . as_str ()) . map (LitKind :: Char) . map_err (| _ | panic ! ("failed to unescape char literal")) ; } token :: Integer => return integer_lit (symbol , suffix) , token :: Float => return float_lit (symbol , suffix) , token :: Str => { let s = symbol . as_str () ; let symbol = if s . contains ('\\') { let mut buf = String :: with_capacity (s . len ()) ; unescape_str (s , # [inline (always)] | _ , res | match res { Ok (c) => buf . push (c) , Err (err) => { assert ! (! err . is_fatal () , "failed to unescape string literal") } } ,) ; Symbol :: intern (& buf) } else { symbol } ; LitKind :: Str (symbol , ast :: StrStyle :: Cooked) } token :: StrRaw (n) => { LitKind :: Str (symbol , ast :: StrStyle :: Raw (n)) } token :: ByteStr => { let s = symbol . as_str () ; let mut buf = Vec :: with_capacity (s . len ()) ; unescape_byte_str (s , | _ , res | match res { Ok (b) => buf . push (b) , Err (err) => { assert ! (! err . is_fatal () , "failed to unescape string literal") } }) ; LitKind :: ByteStr (ByteSymbol :: intern (& buf) , StrStyle :: Cooked) } token :: ByteStrRaw (n) => { let buf = symbol . as_str () . to_owned () . into_bytes () ; LitKind :: ByteStr (ByteSymbol :: intern (& buf) , StrStyle :: Raw (n)) } token :: CStr => { let s = symbol . as_str () ; let mut buf = Vec :: with_capacity (s . len ()) ; unescape_c_str (s , | _span , res | match res { Ok (MixedUnit :: Char (c)) => { buf . extend_from_slice (c . get () . encode_utf8 (& mut [0 ; 4]) . as_bytes ()) } Ok (MixedUnit :: HighByte (b)) => buf . push (b . get ()) , Err (err) => { assert ! (! err . is_fatal () , "failed to unescape C string literal") } }) ; buf . push (0) ; LitKind :: CStr (ByteSymbol :: intern (& buf) , StrStyle :: Cooked) } token :: CStrRaw (n) => { let mut buf = symbol . as_str () . to_owned () . into_bytes () ; buf . push (0) ; LitKind :: CStr (ByteSymbol :: intern (& buf) , StrStyle :: Raw (n)) } token :: Err (guar) => LitKind :: Err (guar) , }) } }